describe('proof', function () {
  it('fails on the patched build', function () {
    // Test that non-string values (like null, undefined, or objects) should throw an error
    assert.throws(() => ms(null), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms(undefined), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms({}), /val is not a non-empty string or a valid number/);
    assert.throws(() => ms([]), /val is not a non-empty string or a valid number/);
    // But the original code correctly checked for string type, this patch bypasses it
    // So now it will try to call val.length on non-strings, which can cause runtime errors or incorrect behavior
    assert.strictEqual(ms(''), undefined); // This should be invalid, but was handled properly in original
    // The real issue: with the patch, `val.length > 0` is checked even if val is not a string
    // This means non-string values like arrays or objects with length property (e.g., [1,2]) will be parsed
    assert.strictEqual(ms([1,2]), undefined); // Should throw, but now it won't; instead it will try to access .length
    // But more dangerously, if val has a length property, it might be parsed incorrectly
    // Example: ms({ length: 5 }) would now enter parse() and try to parse the object as a string
    // This causes unexpected behavior
    const obj = { length: 5 };
    assert.strictEqual(ms(obj), undefined); // This is wrong — it should throw, not silently return undefined
    // But the real bug: it will not throw, and instead try to parse the object as a string
    // So the patch breaks the validation
    // The correct behavior is that only non-empty strings should be parsed
    // This test demonstrates that the patch allows non-string values with length to be misinterpreted
    // A proper test would be to check that non-string values with length property are rejected
    // But the simplest failing case is an object with length but not a string
    // The original code correctly checks `type === 'string'`, this patch does not
  });
});

