describe('proof', function () {
  it('fails on the patched build', function () {
    // The original regex included 's' as a valid suffix for 'seconds', but the patch removed the '?' after 's' in 'seconds?|secs?|s', so 's' alone should still match
    // However, the change removes the optional 's' in 'seconds?|secs?|s', which actually makes it less permissive
    // The original regex allowed 'seconds', 'second', 'secs', 'sec', 's' (all with optional 's' at the end)
    // The new regex does not allow 's' as a valid unit because 's' is now part of 'seconds|secs|s' without being optional
    // But actually, the regex change removes '?' from 'seconds?|secs?|s' → 'seconds|secs|s', so 's' is now required to be matched literally
    // This means '1s' should still work, but the issue is that '1sec' or '1secs' might break? Let's test '1s'
    assert.strictEqual(ms('1s'), 1000);
    assert.strictEqual(ms('1sec'), 1000);
    assert.strictEqual(ms('1secs'), 1000);
    assert.strictEqual(ms('1second'), 1000);
    assert.strictEqual(ms('1seconds'), 1000);
    // The change actually breaks 's' because the original had 'seconds?|secs?|s' which allowed 's' as a standalone
    // But the new regex has 'seconds|secs|s' which still matches 's'
    // Wait, this seems equivalent. Let's reconsider.
    // The original: 'seconds?|secs?|s' → matches 'seconds', 'second', 'secs', 'sec', 's'
    // The new: 'seconds|secs|s' → matches 'seconds', 'secs', 's'
    // So 'second' and 'sec' no longer match!
    assert.strictEqual(ms('1second'), 1000); // This should fail after the change
    assert.strictEqual(ms('1sec'), 1000); // This should fail after the change
  });
});

